typedef unsigned int size_t;

extern "C" void arch_free(void *) __asm__("arch_free__FPv");
extern void *allocator_free_lists[16];
__asm__(".equ arch_free__FPv, 0x002AC768");
__asm__(".equ allocator_free_lists, 0x003E5628");

template<class T>
class vector
{
  T *start;
  T *finish;
  T *end_of_storage;

public:
  ~vector()
  {
    size_t count = end_of_storage - start;
    if (count)
    {
      size_t bytes = count * sizeof(T);
      if (bytes > 128)
        arch_free(start);
      else
      {
        size_t index = ((bytes + 7) >> 3) - 1;
        *(void **)start = allocator_free_lists[index];
        allocator_free_lists[index] = start;
      }
    }
  }
};

